package br.com.loja.order;import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.math.BigDecimal;@Entity @Table(name="order_items")public class OrderItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@JsonIgnore @ManyToOne(optional=false)private CustomerOrder order;private Long productId;private String productName;private Integer quantity;@Column(precision=12,scale=2)private BigDecimal unitPrice;@Column(precision=12,scale=2)private BigDecimal subtotal;public OrderItem(){}public OrderItem(Long p,String n,Integer q,BigDecimal price){productId=p;productName=n;quantity=q;unitPrice=price;subtotal=price.multiply(BigDecimal.valueOf(q));}public void setOrder(CustomerOrder o){order=o;}public Long getId(){return id;}public Long getProductId(){return productId;}public String getProductName(){return productName;}public Integer getQuantity(){return quantity;}public BigDecimal getUnitPrice(){return unitPrice;}public BigDecimal getSubtotal(){return subtotal;}}